            read_channels(channels, self.stream_channels_asis),
            tuple(t.name for t in next_tasks.values() if not t.writes),
            patch_checkpoint_map(saved.config, saved.metadata),
                    CONFIG_KEY_CHECKPOINT_NS: checkpoint_ns,
